function say(x){$('#status').textContent=x} function csv(text){const rows=[];let r=[],v='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&q&&n==='"'){v+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){r.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;r.push(v);if(r.some(x=>x!==''))rows.push(r);r=[];v=''}else v+=c}r.push(v);if(r.some(x=>x!==''))rows.push(r);const h=rows.shift()||[];return rows.map(x=>Object.fromEntries(h.map((k,i)=>[k.replace(/^\uFEFF/,''),x[i]||''])))}
