$('#rtBtn').onclick=async()=>{let key=$('#apiKey').value.trim(),url=$('#rtUrl').value.trim();if(!key)return say('リアルタイム情報にはODPT APIキーを入力してください。');if(!/acl:consumerKey=/.test(url))url+=(url.includes('?')?'&':'?')+'acl:consumerKey='+encodeURIComponent(key);try{say('ODPTリアルタイム情報を取得中…');let r=await fetch(url);if(!r.ok)throw Error(r.status+' '+r.statusText);state.realtime=decodeRt(new Uint8Array(await r.arrayBuffer()));state.realtimeUpdated=new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});showNext();say('リアルタイム情報を反映しました。遅延情報がある便に表示しています。')}catch(e){say('リアルタイム情報を取得できませんでした（CORSまたはURL・APIキーを確認）: '+e.message)}};
